1	//! The core of `monokl search`: a query in, fully ranked and deduplicated blocks out.
2	//!
3	//! Nothing here caps, budgets, serializes or prints. Callers get every surviving block with the counts needed to
4	//! describe what was left out, and apply their own budget.
5	
6	use std::collections::BTreeSet;
7	use std::io;
8	
9	use camino::{Utf8Path, Utf8PathBuf};
10	use grep_matcher::Matcher;
11	use grep_regex::{RegexMatcher, RegexMatcherBuilder};
12	use rayon::prelude::*;
13	use rustc_hash::{FxHashMap, FxHashSet};
14	
15	use crate::analysis::registry::AnalyzerRegistry;
16	use crate::dedup::dedup_blocks;
17	use crate::error::{MonoklError, Result};
18	use crate::file_io::FileIoError;
19	use crate::query::{Modifier, ParsedTerm, QueryPlan, parse};
20	use crate::rank::{rank_blocks, tokenize_block};
21	use crate::text_search::{DEFAULT_MAX_FILES, TextSearchOptions, TextSearchResult, search_files};
22	use crate::tokens::tokenize;
23	use crate::types::{CodeBlock, Diagnostic, DiagnosticKind, Language, LineHit, RankedBlock};
24	
25	/// What to search for and where.
26	#[derive(Clone, Copy, Debug)]
27	pub struct SearchRequest<'a> {
28	    /// The directory to search; it is canonicalized first.
29	    pub root: &'a Utf8Path,
30	    /// The query text, in the syntax [`parse`] reads, or a literal when `exact` is set.
31	    pub query: &'a str,
32	    /// Treats the whole query as one literal term, operators and quotes included.
33	    pub exact: bool,
34	    /// Searches test files too.
35	    pub allow_tests: bool,
36	    /// Skips hidden files and what `.gitignore` and `.ignore` files exclude: inside the root and, within a git
37	    /// repository, in its parent directories up to the repository root.
38	    pub respect_ignore_files: bool,
39	    /// Restricts the search to one language; only TypeScript and JavaScript are supported.
40	    pub language: Option<Language>,
41	}
42	
43	/// Everything a search found, best first and uncapped.
44	#[derive(Clone, Debug)]
45	pub struct SearchResult {
46	    /// Deduplicated blocks with 1-based, contiguous ranks.
47	    pub ranked: Vec<RankedBlock>,
48	    /// Files with at least one line matching a positive term, kept or not.
49	    pub files_total: u64,
50	    /// Whether `files_total` exceeded the file ceiling, so some matching files were never examined.
51	    pub ceiling_hit: bool,
52	    /// What was skipped or only partly understood, in a deterministic order.
53	    pub diagnostics: Vec<Diagnostic>,
54	}
55	
56	impl SearchResult {
57	    fn empty() -> Self {
58	        Self { ranked: Vec::new(), files_total: 0, ceiling_hit: false, diagnostics: Vec::new() }
59	    }
60	
61	    fn skipped(message: impl Into<String>) -> Self {
62	        Self { diagnostics: vec![skipped(None, message)], ..Self::empty() }
63	    }
64	}
65	
66	/// Runs a search over `request.root` and returns ranked blocks.
67	///
68	/// Text search finds the lines matching the query's positive terms; files with a line matching an excluded term, or
69	/// lacking a match for a required term, drop out. Each remaining file goes to the analyzer that owns it, and only
70	/// blocks containing a matching line are kept, ranked with BM25 and deduplicated. A matching line belongs to the
71	/// smallest block containing it, so a class or object literal keeps only the matches outside its members and is
72	/// dropped when it has none. Files no analyzer supports are ignored without a diagnostic.
73	///
74	/// BM25 query terms are the lowercase [`tokenize`] output of each non-excluded literal term. Regex terms select
75	/// lines and appear in `matched_keywords` but add no BM25 terms. A query with only excluded terms has nothing to
76	/// search for and returns an empty result with one `Skipped` diagnostic.
77	///
78	/// # Errors
79	///
80	/// - [`MonoklError::TooManyTerms`] if the query has too many terms.
81	/// - [`MonoklError::RegexBuild`] if any term is not a valid regex; no file is read first.
82	/// - [`MonoklError::Io`] or [`MonoklError::NonUtf8Path`] if `request.root` cannot be canonicalized.
83	/// - [`MonoklError::Walk`] if the root is not a listable directory.
84	///
85	/// # Examples
86	///
87	/// ```
88	/// use camino::Utf8Path;
89	/// use monokl::analysis::registry::AnalyzerRegistry;
90	/// use monokl::pipeline::{SearchRequest, search};
91	///
92	/// let dir = tempfile::tempdir()?;
93	/// std::fs::write(dir.path().join("a.ts"), "const alpha = 1;\n")?;
94	/// let root = Utf8Path::from_path(dir.path()).ok_or("temp dir is not UTF-8")?;
95	/// let request = SearchRequest {
96	///     root,
97	///     query: "alpha",
98	///     exact: false,
99	///     allow_tests: false,
100	///     respect_ignore_files: true,
101	///     language: None,
102	/// };
103	///
104	/// // With no analyzer registered, the file matches but yields no blocks.
105	/// let result = search(&AnalyzerRegistry::new(Vec::new()), &request)?;
106	/// assert_eq!(result.files_total, 1);
107	/// assert!(result.ranked.is_empty());
108	/// # Ok::<(), Box<dyn std::error::Error>>(())
109	/// ```
110	pub fn search(registry: &AnalyzerRegistry, request: &SearchRequest<'_>) -> Result<SearchResult> {
111	    search_with_ceiling(registry, request, DEFAULT_MAX_FILES)
112	}
113	
114	/// A block annotated with its matches, and its tokens.
115	type Candidate = (CodeBlock, Vec<String>);
116	
117	/// [`search`] with the file ceiling as a parameter, so tests can reach it without 100,000 files.
118	fn search_with_ceiling(
119	    registry: &AnalyzerRegistry,
120	    request: &SearchRequest<'_>,
121	    max_files: usize,
122	) -> Result<SearchResult> {
123	    let SearchRequest { root, query, exact, allow_tests, respect_ignore_files, language } = *request;
124	    if let Some(language) = language
125	        && !is_supported(language)
126	    {
127	        return Ok(SearchResult::skipped(format!(
128	            "language {language:?} not supported in v1; only TypeScript/JavaScript"
129	        )));
130	    }
131	
132	    let terms = if exact {
133	        if query.trim().is_empty() {
134	            Vec::new()
135	        } else {
136	            vec![ParsedTerm { modifier: Modifier::Optional, pattern: regex::escape(query), is_regex: false }]
137	        }
138	    } else {
139	        parse(query)?
140	    };
141	    let plan = QueryPlan::from_terms(terms);
142	    let patterns = plan.search_patterns();
143	    if patterns.is_empty() {
144	        return Ok(SearchResult::skipped("query has no positive terms; add a term without a leading `-`"));
145	    }
146	
147	    // Every term, excluded ones too, compiles before any file is read, so an invalid one fails the whole query.
148	    let matchers = plan.terms.iter().map(|term| compile(&term.pattern)).collect::<Result<Vec<_>>>()?;
149	    let root = canonicalize(root)?;
150	
151	    let found = search_files(&root, &patterns, &TextSearchOptions { allow_tests, respect_ignore_files, max_files })?;
152	    let mut diagnostics = text_search_diagnostics(&found);
153	
154	    // The ceiling must not apply here: an excluded file past it would wrongly survive.
155	    let excluded_files = if found.hits.is_empty() || plan.excluded.is_empty() {
156	        BTreeSet::new()
157	    } else {
158	        let excluded_patterns: Vec<&str> = plan.excluded.iter().map(|&i| plan.terms[i].pattern.as_str()).collect();
159	        let excluded = search_files(
160	            &root,
161	            &excluded_patterns,
162	            &TextSearchOptions { allow_tests, respect_ignore_files, max_files: usize::MAX },
163	        )?;
164	        // The walk is the same, so only a file unreadable for the excluded patterns alone is new.
165	        for path in &excluded.unreadable {
166	            if !found.unreadable.contains(path) {
167	                diagnostics.push(unreadable_diagnostic(path));
168	            }
169	        }
170	        excluded.hits.into_keys().collect()
171	    };
172	
173	    let survivors: Vec<(&Utf8PathBuf, &Vec<LineHit>)> = found
174	        .hits
175	        .iter()
176	        .filter(|(path, _)| !excluded_files.contains(*path))
177	        .filter(|(_, hits)| plan.required.iter().all(|&i| hits.iter().any(|hit| matches_text(&matchers[i], &hit.text))))
178	        .collect();
179	    // Files are analyzed on separate threads, but each result is kept in path order, so the output never depends on
180	    // which thread finished first.
181	    let ctx = FileContext { registry, plan: &plan, matchers: &matchers, language };
182	    let per_file: Vec<(Vec<Candidate>, Vec<Diagnostic>)> = survivors
183	        .into_par_iter()
184	        .map(|(path, hits)| {
185	            let (mut blocks, mut file_diagnostics) = (Vec::new(), Vec::new());
186	            retrieve_blocks(&ctx, path, hits, &read_source, &mut blocks, &mut file_diagnostics);
187	            (blocks, file_diagnostics)
188	        })
189	        .collect();
190	    let mut candidates: Vec<Candidate> = Vec::new();
191	    for (blocks, file_diagnostics) in per_file {
192	        candidates.extend(blocks);
193	        diagnostics.extend(file_diagnostics);
194	    }
195	
196	    let bm25_terms = bm25_terms(&plan);
197	    let df = document_frequencies(&candidates, &bm25_terms);
198	    let bm25_terms: Vec<&str> = bm25_terms.iter().map(String::as_str).collect();
199	    let ranked = dedup_blocks(rank_blocks(candidates, &bm25_terms, &df));
200	
201	    Ok(SearchResult { ranked, files_total: found.files_total, ceiling_hit: found.ceiling_hit, diagnostics })
202	}
203	
204	/// Returns whether `language` has an analyzer path in v1.
205	fn is_supported(language: Language) -> bool {
206	    match language {
207	        Language::TypeScript | Language::JavaScript => true,
208	        Language::Rust | Language::Python => false,
209	    }
210	}
211	
212	/// Compiles one term the way text search does, case-insensitively, so a term can never match differently here.
213	fn compile(pattern: &str) -> Result<RegexMatcher> {
214	    Ok(RegexMatcherBuilder::new().case_insensitive(true).build(pattern)?)
215	}
216	
217	fn canonicalize(root: &Utf8Path) -> Result<Utf8PathBuf> {
218	    let path = root.as_std_path().canonicalize().map_err(|source| FileIoError::read(root, source))?;
219	    Utf8PathBuf::from_path_buf(path).map_err(|path| MonoklError::NonUtf8Path { path })
220	}
221	
222	/// A file's text, and whether getting it meant replacing bytes that are not UTF-8.
223	struct Source {
224	    text: String,
225	    lossy: bool,
226	}
227	
228	/// Reads `path`, replacing each invalid UTF-8 sequence with U+FFFD so the file is still searched and extracted.
229	fn read_source(path: &Utf8Path) -> io::Result<Source> {
230	    let bytes = std::fs::read(path)?;
231	    Ok(match String::from_utf8(bytes) {
232	        Ok(text) => Source { text, lossy: false },
233	        Err(err) => Source { text: String::from_utf8_lossy(err.as_bytes()).into_owned(), lossy: true },
234	    })
235	}
236	
237	/// Whether `matcher` matches `text`. Matching in memory cannot fail, so an error counts as no match.
238	fn matches_text(matcher: &RegexMatcher, text: &str) -> bool {
239	    matches!(matcher.is_match(text.as_bytes()), Ok(true))
240	}
241	
242	fn skipped(path: Option<&Utf8Path>, message: impl Into<String>) -> Diagnostic {
243	    Diagnostic { kind: DiagnosticKind::Skipped, path: path.map(Utf8Path::to_owned), message: message.into() }
244	}
245	
246	fn unreadable_diagnostic(path: &Utf8Path) -> Diagnostic {
247	    skipped(Some(path), "file could not be read")
248	}
249	
250	/// Turns what text search could not read into diagnostics: one per unreadable path, then one per non-zero count.
251	fn text_search_diagnostics(found: &TextSearchResult) -> Vec<Diagnostic> {
252	    let mut diagnostics: Vec<Diagnostic> = found.unreadable.iter().map(|path| unreadable_diagnostic(path)).collect();
253	    if found.non_utf8_paths > 0 {
254	        diagnostics.push(skipped(None, format!("{} files skipped: path is not valid UTF-8", found.non_utf8_paths)));
255	    }
256	    if found.walk_errors_without_path > 0 {
257	        diagnostics.push(skipped(
258	            None,
259	            format!("{} directory walk errors did not name a UTF-8 path", found.walk_errors_without_path),
260	        ));
261	    }
262	    diagnostics
263	}
264	
265	/// What block retrieval needs besides the file itself.
266	struct FileContext<'a> {
267	    registry: &'a AnalyzerRegistry,
268	    plan: &'a QueryPlan,
269	    matchers: &'a [RegexMatcher],
270	    language: Option<Language>,
271	}
272	
273	/// The TypeScript analyzer owns both languages, so the `--language` filter goes by extension.
274	fn has_language_extension(language: Language, path: &Utf8Path) -> bool {
275	    match language {
276	        Language::TypeScript => matches!(path.extension(), Some("ts" | "tsx" | "mts" | "cts")),
277	        Language::JavaScript => matches!(path.extension(), Some("js" | "jsx" | "mjs" | "cjs")),
278	        Language::Rust | Language::Python => false,
279	    }
280	}
281	
282	/// Analyzes one surviving file and pushes the annotated blocks that contain a matching line onto `out`.
283	fn retrieve_blocks(
284	    ctx: &FileContext<'_>,
285	    path: &Utf8Path,
286	    hits: &[LineHit],
287	    read: &dyn Fn(&Utf8Path) -> io::Result<Source>,
288	    out: &mut Vec<(CodeBlock, Vec<String>)>,
289	    diagnostics: &mut Vec<Diagnostic>,
290	) {
291	    let Some(analyzer) = ctx.registry.analyzer_for(path) else { return };
292	    if ctx.language.is_some_and(|language| !has_language_extension(language, path)) {
293	        return;
294	    }
295	    let Source { text, lossy } = match read(path) {
296	        Ok(source) => source,
297	        Err(err) => {
298	            diagnostics.push(skipped(Some(path), format!("could not read source: {err}")));
299	            return;
300	        }
301	    };
302	    if lossy {
303	        diagnostics.push(Diagnostic {
304	            kind: DiagnosticKind::LossyRead,
305	            path: Some(path.to_owned()),
306	            message: "invalid UTF-8 replaced with U+FFFD".to_owned(),
307	        });
308	    }
309	    let analysis = match analyzer.analyze(path, Box::new(move || Ok(text))) {
310	        Ok(analysis) => analysis,
311	        Err(err) => {
312	            diagnostics.push(skipped(Some(path), format!("could not analyze: {err}")));
313	            return;
314	        }
315	    };
316	    if analysis.had_parse_errors {
317	        let message = analysis
318	            .degradation
319	            .map_or_else(|| "parse errors; blocks may be incomplete".to_owned(), |reason| reason.to_string());
320	        diagnostics.push(Diagnostic { kind: DiagnosticKind::Degraded, path: Some(path.to_owned()), message });
321	    }
322	    let positive: Vec<&RegexMatcher> = ctx
323	        .plan
324	        .terms
325	        .iter()
326	        .zip(ctx.matchers)
327	        .filter(|(term, _)| term.modifier != Modifier::Excluded)
328	        .map(|(_, matcher)| matcher)
329	        .collect();
330	    let line_matches = |text: &str| positive.iter().any(|matcher| matches_text(matcher, text));
331	    for (block, inside) in analysis.blocks.iter().zip(owned_hits(&analysis.blocks, hits, &line_matches)) {
332	        if inside.is_empty() {
333	            continue;
334	        }
335	        let matched_keywords = ctx
336	            .plan
337	            .terms
338	            .iter()
339	            .zip(ctx.matchers)
340	            .filter(|(term, _)| term.modifier != Modifier::Excluded)
341	            .filter(|(_, matcher)| inside.iter().any(|hit| matches_text(matcher, &hit.text)))
342	            .map(|(term, _)| keyword(term))
343	            .collect();
344	        let annotated = CodeBlock {
345	            matched_lines: inside.iter().map(|hit| hit.line_number).collect(),
346	            matched_keywords,
347	            ..block.clone()
348	        };
349	        let tokens = tokenize_block(&annotated);
350	        out.push((annotated, tokens));
351	    }
352	}
353	
354	/// Splits `hits` among `blocks`: a hit goes to every block whose own text on that line matches, except one that holds
355	/// a smaller such block. A class or object therefore keeps only the matches outside its members, and a block with
356	/// none is dropped by the caller. A block can start or end in the middle of a line (`} b() {`, `}, // note`), so only
357	/// the part of the line inside the block counts, which sends the match to the member or holder that actually contains
358	/// the text. Where no block's own text matches (a match across the edge of every block on the line) every block on the
359	/// line keeps the hit, so a match is never lost. Blocks that only share a line are not nested, so each keeps it.
360	/// `hits` must be in line order; each block's hits are too.
361	fn owned_hits<'h>(
362	    blocks: &[CodeBlock],
363	    hits: &'h [LineHit],
364	    line_matches: &dyn Fn(&str) -> bool,
365	) -> Vec<Vec<&'h LineHit>> {
366	    let mut containing: Vec<Vec<usize>> = vec![Vec::new(); hits.len()];
367	    for (index, block) in blocks.iter().enumerate() {
368	        let first = hits.partition_point(|hit| hit.line_number < block.line_start);
369	        let inside = hits[first..].iter().take_while(|hit| hit.line_number <= block.line_end).count();
370	        for slot in &mut containing[first..first + inside] {
371	            slot.push(index);
372	        }
373	    }
374	    let range = |index: usize| (blocks[index].line_start, blocks[index].line_end);
375	    let own_text_matches = |index: usize, line: usize| {
376	        let block = &blocks[index];
377	        block.code.split('\n').nth(line - block.line_start).is_some_and(line_matches)
378	    };
379	    let mut per_block = vec![Vec::new(); blocks.len()];
380	    for (hit, containing_all) in hits.iter().zip(&containing) {
381	        let matching: Vec<usize> =
382	            containing_all.iter().copied().filter(|&index| own_text_matches(index, hit.line_number)).collect();
383	        let candidates = if matching.is_empty() { containing_all } else { &matching };
384	        for &outer in candidates {
385	            let (start, end) = range(outer);
386	            let holds_a_smaller_block = candidates.iter().any(|&inner| {
387	                let (inner_start, inner_end) = range(inner);
388	                inner_start >= start && inner_end <= end && (inner_start, inner_end) != (start, end)
389	            });
390	            if !holds_a_smaller_block {
391	                per_block[outer].push(hit);
392	            }
393	        }
394	    }
395	    per_block
396	}
397	
398	/// Returns the text the user typed for `term`: a regex as written, a literal with its escaping undone.
399	fn keyword(term: &ParsedTerm) -> String {
400	    if term.is_regex {
401	        return term.pattern.clone();
402	    }
403	    // `regex::escape` only ever puts a backslash before the character it escapes.
404	    let mut text = String::with_capacity(term.pattern.len());
405	    let mut chars = term.pattern.chars();
406	    while let Some(ch) = chars.next() {
407	        if ch == '\\' {
408	            text.extend(chars.next());
409	        } else {
410	            text.push(ch);
411	        }
412	    }
413	    text
414	}
415	
416	/// Returns the BM25 query terms: the tokens of each non-excluded literal term, each once, in query order.
417	fn bm25_terms(plan: &QueryPlan) -> Vec<String> {
418	    let mut seen = FxHashSet::default();
419	    plan.terms
420	        .iter()

