//! Orders matching files by how likely they are to hold the best blocks, from what text search already knows.
//!
//! Nothing here reads or parses a file. The score is a heuristic for the order in which files are analyzed, not a
//! ranking: the block ranker still decides what prints.

use camino::Utf8Path;
use grep_matcher::Matcher;
use grep_regex::RegexMatcher;

use crate::types::LineHit;

/// One file's matching lines and size, the inputs to [`file_score`].
pub(super) struct FileEvidence<'a> {
    /// The path below the search root, with `/` separators.
    pub relative: &'a str,
    pub hits: &'a [LineHit],
    pub size_bytes: u64,
}

/// Weights, in the order they matter: terms hit, then a term in the file's stem, then a term elsewhere in its path,
/// then density of matching lines.
const DISTINCT_TERM: f64 = 4.0;
const STEM_TERM: f64 = 3.0;
const PATH_TERM: f64 = 1.0;

/// Scores a file for analysis order; higher goes first.
///
/// `matchers` are the positive terms' matchers, the same ones that selected the lines. The score adds
///
/// - 4 per term that some hit line matches,
/// - 3 per term the file stem matches, and 1 per term another path component matches,
/// - `ln(1 + hits)` divided by `1 + ln(1 + size in KiB) / 4`, so a small file with many hits beats a large one with
///   the same count.
#[allow(clippy::cast_precision_loss, reason = "counts and sizes this large lose nothing that changes an ordering")]
pub(super) fn file_score(matchers: &[&RegexMatcher], file: &FileEvidence<'_>) -> f64 {
    let path = Utf8Path::new(file.relative);
    let stem = path.file_stem().unwrap_or_default();
    let mut score = 0.0;
    for matcher in matchers {
        if file.hits.iter().any(|hit| is_match(matcher, &hit.text)) {
            score += DISTINCT_TERM;
        }
        if is_match(matcher, stem) {
            score += STEM_TERM;
        } else if is_match(matcher, file.relative) {
            score += PATH_TERM;
        }
    }
    let kib = file.size_bytes as f64 / 1024.0;
    score + (1.0 + file.hits.len() as f64).ln() / (1.0 + (1.0 + kib).ln() / 4.0)
}

fn is_match(matcher: &RegexMatcher, text: &str) -> bool {
    matches!(matcher.is_match(text.as_bytes()), Ok(true))
}

