    /// Analyzes every matching file, as [`search`] does.
    pub const EVERYTHING: Self = Self { rows: usize::MAX, first_batch: usize::MAX };

    /// The default for a caller that prints `rows` blocks: a first batch of `max(100, 2 * rows)` files.
    #[must_use]
    pub fn for_rows(rows: usize) -> Self {
        Self { rows, first_batch: rows.saturating_mul(2).max(100) }
