    let plan = QueryPlan::from_terms(terms);
    let patterns = plan.search_patterns();
    if patterns.is_empty() {
        return Ok(SearchResult::skipped("query has no positive terms; add a term without a leading `-`"));
    }

    // Every term, excluded ones too, compiles before any file is read, so an invalid one fails the whole query.
    let matchers = plan.terms.iter().map(|term| compile(&term.pattern)).collect::<Result<Vec<_>>>()?;
    let root = canonicalize(root)?;

    let found = search_files(&root, &patterns, &TextSearchOptions { allow_tests, respect_ignore_files, max_files })?;
    let mut diagnostics = text_search_diagnostics(&found);

    // The ceiling must not apply here: an excluded file past it would wrongly survive.
    let excluded_files = if found.hits.is_empty() || plan.excluded.is_empty() {
        BTreeSet::new()
    } else {
        let excluded_patterns: Vec<&str> = plan.excluded.iter().map(|&i| plan.terms[i].pattern.as_str()).collect();
        let excluded = search_files(
            &root,
            &excluded_patterns,
            &TextSearchOptions { allow_tests, respect_ignore_files, max_files: usize::MAX },
        )?;
        // The walk is the same, so only a file unreadable for the excluded patterns alone is new.
        for path in &excluded.unreadable {
            if !found.unreadable.contains(path) {
                diagnostics.push(unreadable_diagnostic(path));
            }
        }
        excluded.hits.into_keys().collect()
    };

    let ctx = FileContext { registry, plan: &plan, matchers: &matchers, language };
    // A file no analyzer takes is dropped here rather than counted against a batch, where it would yield nothing.
    let survivors: Vec<Matched<'_>> = found
        .hits
        .iter()
        .filter(|(path, _)| !excluded_files.contains(*path))
        .filter(|(_, hits)| plan.required.iter().all(|&i| hits.iter().any(|hit| matches_text(&matchers[i], &hit.text))))
        .filter(|(path, _)| analyzer_for(&ctx, path).is_some())
        .collect();
    let files_eligible = survivors.len();
    let survivors = if files_eligible <= analysis.first_batch { survivors } else { prioritize(&ctx, &root, survivors) };

    let bm25_terms = bm25_terms(&plan);
    let query_terms: Vec<&str> = bm25_terms.iter().map(String::as_str).collect();
    let mut candidates: Vec<Candidate> = Vec::new();
    let mut per_file_diagnostics: Vec<(&Utf8PathBuf, Vec<Diagnostic>)> = Vec::new();
    let (mut analyzed, mut batch) = (0, analysis.first_batch.max(1));
    let ranked = loop {
        let end = analyzed.saturating_add(batch).min(survivors.len());
        // Files are analyzed on separate threads, but each result is kept in batch order, so the output never depends
        // on which thread finished first.
        let results: Vec<(Vec<Candidate>, Vec<Diagnostic>)> = survivors[analyzed..end]
            .par_iter()
            .map(|&(path, hits)| {
                let (mut blocks, mut file_diagnostics) = (Vec::new(), Vec::new());
                retrieve_blocks(&ctx, path, hits, &read_source, &mut blocks, &mut file_diagnostics);
                (blocks, file_diagnostics)
            })
            .collect();
        for (&(path, _), (blocks, file_diagnostics)) in survivors[analyzed..end].iter().zip(results) {
            candidates.extend(blocks);
            if !file_diagnostics.is_empty() {
                per_file_diagnostics.push((path, file_diagnostics));
            }
        }
        analyzed = end;
        batch = batch.saturating_mul(2);

        let last = analyzed == survivors.len();
        // BM25 statistics are the analyzed blocks'. The last round owns the candidates; earlier ones rank a copy.
        let blocks = if last { std::mem::take(&mut candidates) } else { candidates.clone() };
        let df = document_frequencies(&blocks, &bm25_terms);
        let ranked = dedup_blocks(rank_blocks(blocks, &query_terms, &df));
        if last || ranked.len() >= analysis.rows {
            break ranked;
        }
    };
    // Per-file diagnostics keep path order, as they would had every file been analyzed in that order.
    per_file_diagnostics.sort_by(|a, b| a.0.cmp(b.0));
    diagnostics.extend(per_file_diagnostics.into_iter().flat_map(|(_, file_diagnostics)| file_diagnostics));

    Ok(SearchResult {
        ranked,
        files_total: found.files_total,
        ceiling_hit: found.ceiling_hit,
        files_eligible: files_eligible as u64,
        files_analyzed: analyzed as u64,
        diagnostics,
    })
}

/// Sorts `files` by descending [`file_score`], ties by path, so the order never depends on thread timing.
fn prioritize<'a>(ctx: &FileContext<'_>, root: &Utf8Path, files: Vec<Matched<'a>>) -> Vec<Matched<'a>> {
    let positive: Vec<&RegexMatcher> = ctx
        .plan
        .terms
        .iter()
        .zip(ctx.matchers)
        .filter(|(term, _)| term.modifier != Modifier::Excluded)
        .map(|(_, matcher)| matcher)
        .collect();
    let mut scored: Vec<(f64, Matched<'a>)> = files
        .into_par_iter()
        .map(|(path, hits)| {
            let relative = path.strip_prefix(root).unwrap_or(path).as_str();
            // A file that cannot be statted scores as empty; reading it later reports the failure.
            let size_bytes = std::fs::metadata(path).map_or(0, |metadata| metadata.len());
            (file_score(&positive, &FileEvidence { relative, hits, size_bytes }), (path, hits))
        })
        .collect();
    scored.sort_by(|a, b| b.0.total_cmp(&a.0).then_with(|| a.1.0.cmp(b.1.0)));
    scored.into_iter().map(|(_, file)| file).collect()
}

