import json, os, re, subprocess, sys
from pathlib import Path

ROOT = Path("/Users/gabe/Projects/monokl/.claude/worktrees/agent-ac23bc934f4c852ac")
BIN = ROOT / "target/release/monokl"
REPOS = {r: ROOT / "target/rg-compare" / r for r in ("zustand", "zod", "axios")}
if "--typescript" in sys.argv:
    REPOS = {"typescript": ROOT / "target/bench/typescript"}
KS = ["all", "100", "50"]
TS_GLOBS = ["*.ts", "*.tsx", "*.mts", "*.cts", "*.js", "*.jsx", "*.mjs", "*.cjs", "!*.d.ts", "!*.d.mts", "!*.d.cts"]
DECL = r"^(?:export\s+)?(?:default\s+)?(?:declare\s+)?(?:abstract\s+)?(?:async\s+)?(?:function\*?|class|interface|type|enum|const|let|var)\s+([A-Za-z_][A-Za-z0-9_]{3,})"
BROAD = ["string", "error", "type", "config", "options", "value", "request", "parse", "schema", "default", "promise",
         "handler", "headers", "data", "result", "name", "array", "object", "number", "check", "message", "callback",
         "params", "return"]


def sample(path, n):
    g = [a for x in TS_GLOBS for a in ("--glob", x)]
    out = subprocess.run(["rg", "--no-filename", "--only-matching", "--no-line-number", "--replace", "$1", *g, "-e", DECL, "."],
                         cwd=path, capture_output=True, text=True).stdout
    names = sorted(set(out.split()) - {"tests"})
    step = len(names) / n
    return [names[int(i * step)] for i in range(n)]


def run(path, query, k, extra=()):
    env = dict(os.environ, MONOKL_FIRST_BATCH=k, MONOKL_TRACE="1")
    p = subprocess.run([str(BIN), "search", *extra, query, "."], cwd=path, capture_output=True, text=True, env=env)
    rows = []
    for line in p.stdout.splitlines():
        if line.startswith("  "):
            f = line.strip().split(",")
            if len(f) > 3 and f[1].isdigit() and f[2].isdigit():
                rows.append((f[0], int(f[1]), int(f[2])))
    m = re.search(r"analyzed (\d+) of (\d+)", p.stderr)
    return rows, (int(m.group(1)), int(m.group(2))) if m else (0, 0)


queries = []
for repo, path in REPOS.items():
    for w in BROAD:
        queries.append((repo, path, "broad", w))
    if repo != "typescript":
        for t in sample(path, 25):
            queries.append((repo, path, "ident", t))
if "--typescript" not in sys.argv:
    for line in (ROOT / "scripts/rg-compare.questions").read_text().splitlines():
        if line.strip() and not line.startswith("#"):
            repo, words, *_ = [c.strip() for c in line.split("|")]
            if repo in REPOS:
                queries.append((repo, REPOS[repo], "question", words))
else:
    for t in ["createProgram", "checker node", "parse statement", "emit declaration", "resolve module name", "symbol table"]:
        queries.append(("typescript", REPOS["typescript"], "question", t))

total = same = trunc = 0
diffs = []
for repo, path, kind, q in queries:
    res = {k: run(path, q, k) for k in KS}
    base = res["all"][0]
    total += 1
    truncated = res["100"][1][0] < res["100"][1][1]
    trunc += truncated
    row = {"repo": repo, "kind": kind, "q": q, "eligible": res["all"][1][1], "n_all": len(base)}
    for k in ("100", "50"):
        rows = res[k][0]
        ch = [i + 1 for i in range(max(len(base), len(rows))) if (base[i] if i < len(base) else None) != (rows[i] if i < len(rows) else None)]
        row[k] = ch
    row["truncated100"] = truncated
    if not row["100"]:
        same += 1
    diffs.append(row)
print(json.dumps({"total": total, "identical_100": same, "truncated_100": trunc,
                  "identical_50": sum(1 for r in diffs if not r["50"]), "rows": diffs}, indent=1))

